INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('devops', 'ha-dr', 'overview', 'What is the core distinction between HA (High Availability) and DR (Disaster Recovery)?', '["They are two names for the same set of mechanisms", "HA keeps a system running through partial failure with no real downtime; DR recovers from total failure with some acceptable downtime", "HA only applies to databases; DR only applies to application servers", "DR is a subset of HA, not a separate concern"]', 1, 'HA handles partial failure (a node dies, traffic shifts automatically); DR handles total failure (an entire region goes down, requiring failover with some accepted downtime) -- confusing the two leads to bad architecture, since HA mechanisms alone don''t protect against a full region outage.', 'beginner'),
('devops', 'ha-dr', 'overview', 'What do RTO and RPO each measure?', '["RTO measures data loss tolerance; RPO measures downtime tolerance", "RTO measures how long you can be down (Recovery Time Objective); RPO measures how much data you can afford to lose, measured as time since the last durable copy (Recovery Point Objective)", "Both measure the exact same thing, just in different units", "RTO applies only to databases; RPO applies only to compute"]', 1, 'RTO = Recovery Time Objective (downtime tolerance); RPO = Recovery Point Objective (data-loss tolerance, measured as time since last durable copy). These two numbers drive every HA/DR architecture decision.', 'beginner'),
('devops', 'ha-dr', 'overview', 'Why can a Kubernetes Deployment with 3 replicas and no anti-affinity rule still fail to survive a single node failure?', '["Kubernetes always spreads replicas across nodes automatically, so this can''t happen", "Without an explicit anti-affinity rule, all 3 replicas could land on the same node by default, so one node failure kills all of them at once", "3 replicas is never enough regardless of configuration", "Anti-affinity only matters for StatefulSets, not Deployments"]', 1, 'HA is not automatic in Kubernetes -- anti-affinity rules must be explicitly configured to spread pods across nodes/zones; without them, the scheduler can place every replica on one node.', 'intermediate'),
('devops', 'ha-dr', 'overview', 'Among the four DR strategy tiers described (Backup and Restore, Pilot Light, Warm Standby, Active/Active), which offers RTO in seconds but is also the most expensive?', '["Backup and Restore", "Pilot Light", "Warm Standby", "Active/Active"]', 3, 'Active/Active runs both regions serving production traffic simultaneously, giving RTO in seconds and near-zero RPO -- at the highest cost and with real cross-region data-consistency challenges.', 'intermediate'),
('devops', 'ha-dr', 'overview', 'What does a PodDisruptionBudget specifically guarantee?', '["That pods are never restarted under any circumstances", "A minimum number of replicas stay running during voluntary disruptions like node drains or cluster upgrades", "That a Deployment always has exactly 3 replicas", "That database connections are never dropped"]', 1, 'A PodDisruptionBudget (e.g. minAvailable: 2) ensures voluntary disruptions like node drains don''t take available replicas below a safe minimum -- it protects against planned maintenance events, not unplanned crashes.', 'beginner'),
('devops', 'ha-dr', 'fundamentals', 'Roughly how long does RDS Multi-AZ automatic failover typically take, per the fundamentals content?', '["Under 5 seconds", "Roughly 60-120 seconds", "About 30 minutes", "Several hours"]', 1, 'RDS Multi-AZ failover to the synchronous standby in a different AZ is typically under 60-120 seconds, managed automatically by AWS without manual replication-slot or promotion steps.', 'intermediate'),
('devops', 'ha-dr', 'fundamentals', 'What real problem occurs if readiness and liveness probes are conflated -- using the same shallow check for both?', '["Nothing -- they are functionally interchangeable by design", "A pod stuck waiting on a slow dependency gets killed and restarted (liveness) instead of just being pulled from the load balancer until it recovers (readiness), which is usually the wrong response", "The pod will never receive traffic under any condition", "Kubernetes will refuse to schedule the pod at all"]', 1, 'Readiness controls whether a pod receives traffic; liveness controls whether Kubernetes restarts it. Using the same shallow check for both means a pod that''s merely waiting on a slow dependency gets killed instead of just temporarily pulled from load balancing.', 'advanced'),
('devops', 'ha-dr', 'fundamentals', 'Per CAP theorem, what must a distributed system choose between during a network partition, and what do most production systems typically choose for user-facing reads versus money/inventory operations?', '["Consistency or Availability -- most choose AP for user-facing reads and CP for anything involving money/inventory", "Cost or Performance -- most choose Performance for everything", "Latency or Throughput -- most choose Throughput universally", "Durability or Speed -- most choose Speed for financial transactions specifically"]', 0, 'Under a partition, a system must choose Consistency (every read sees the latest write) or Availability (every request gets a response, possibly stale) -- most production systems choose AP for general user-facing reads and CP for money/inventory-critical operations.', 'advanced'),
('devops', 'ha-dr', 'fundamentals', 'Why is running only 2 replicas (instead of 3) considered a real HA risk?', '["2 replicas cost exactly the same as 3, so there''s no reason not to use 3", "Losing 1 replica during a rolling update or node failure leaves zero redundancy at that moment -- with 3, losing 1 still leaves 2 healthy replicas", "Kubernetes does not support exactly 2 replicas as a valid configuration", "2 replicas cannot be load-balanced by a Service at all"]', 1, 'With only 2 replicas, a single failure during a rolling update or node loss leaves zero redundancy -- 3 is the minimum that tolerates one failure while still having redundancy remaining.', 'intermediate'),
('devops', 'ha-dr', 'fundamentals', 'What is the RPO of the Active-Passive (warm) DR tier per the fundamentals table?', '["Near-zero (~0)", "Minutes", "Hours", "Days"]', 1, 'The Active-Passive (warm) tier is listed with an RPO of minutes and RTO of 5-15 minutes, at roughly 1.5x cost -- positioned between the cheaper Backup+Restore tier and the more expensive Active-Active tier.', 'beginner'),
('devops', 'incident', 'overview', 'What defines a P1 severity incident, and what is the rule of thumb when genuinely uncertain between two severity levels?', '["P1 is any bug reported by a VIP customer; always assign the lowest severity when uncertain", "P1 is a complete outage, data loss, or a critical business function fully down; when uncertain, always err toward the higher severity", "P1 only applies to security incidents; uncertainty should default to P4", "P1 requires legal sign-off before it can be declared"]', 1, 'P1 means complete outage/data loss with all-hands response; the stated rule of thumb is to err toward the higher severity when uncertain, since it''s easy to downgrade later but missing a real P1 is expensive.', 'beginner'),
('devops', 'incident', 'overview', 'What is described as the single most important rule in incident response?', '["Always find the root cause before taking any mitigating action", "Restore service first, find root cause second -- every minute spent investigating without mitigating action is a minute of continued downtime", "Never communicate status updates until the incident is fully resolved", "Always roll back to the very first production deployment, regardless of what changed recently"]', 1, 'The content states this as the most important rule: mitigate first (often via rollback), investigate root cause afterward in the post-mortem -- diagnosing instead of acting extends downtime.', 'beginner'),
('devops', 'incident', 'overview', 'In Phase 4 (Mitigate) of the 6-phase incident response framework, what is listed as the fastest mitigation for an incident correlated with a recent deployment?', '["Failing over to a DR region immediately", "Rolling back the last deployment", "Scheduling a post-mortem meeting first", "Filing a bug ticket and waiting for the next sprint"]', 1, 'Rollback is listed first among mitigation options for a deployment-correlated incident -- faster than forward-fixing the actual bug under pressure, and it removes the suspected cause immediately.', 'intermediate'),
('devops', 'incident', 'overview', 'In the worked 5-Whys example for the payment service outage, what was identified as the actual root cause?', '["A hardware failure in the primary database server", "Missing connection pool configuration validation in the deployment pipeline -- new code opened connections without closing them, and staging''s pool_size setting didn''t match production''s", "A DDoS attack overwhelming the payment API", "An expired TLS certificate on the payment gateway"]', 1, 'The 5-Whys chain traces: 500 errors -> DB connection pool exhausted -> new code opened connections without closing -> integration tests didn''t use production-scale DB config -> root cause is the missing connection pool configuration validation in the deployment pipeline itself.', 'advanced'),
('devops', 'incident', 'overview', 'What communication cadence is recommended during an active P1 incident, even when there is nothing new to report?', '["No updates until the incident is fully resolved, to avoid causing panic", "Every 10-15 minutes -- silence during an outage feels worse than uncertainty", "Once every 24 hours via an internal email digest", "Only when a customer specifically asks for a status update"]', 1, 'The content is explicit: communicate every 10-15 minutes even with nothing new to report, since silence during an outage reads as ''nobody''s working on this'' even when that''s false.', 'intermediate'),
('devops', 'incident', 'fundamentals', 'Why should severity classification default to the higher level when genuinely uncertain between two options?', '["Because higher severity always looks better in post-incident metrics", "Because the cost of over-classifying a real incident (extra people paged, resolved faster than strictly needed) is much smaller than the cost of under-classifying one (a real P1 sitting unaddressed for hours as a P3)", "Because company policy legally requires the highest classification whenever there is ambiguity", "Because lower severities do not have defined response times at all"]', 1, 'The fundamentals content states this explicitly as an asymmetric-cost argument: over-classifying wastes some response effort, but under-classifying can leave a genuine P1 unaddressed for hours -- the asymmetry justifies defaulting high when uncertain.', 'intermediate'),
('devops', 'incident', 'fundamentals', 'What distinguishes MTTD from MTTA as incident metrics?', '["MTTD measures how long until an incident is detected (driven by alerting quality); MTTA measures how long until someone acknowledges/responds to the alert (driven by on-call process)", "They are the exact same metric under two different names", "MTTD only applies to P1 incidents; MTTA only applies to P4 incidents", "MTTA measures detection speed; MTTD measures acknowledgment speed -- the reverse pairing"]', 0, 'MTTD (Mean Time To Detect) reflects alerting quality -- how fast something breaking is actually noticed; MTTA (Mean Time To Acknowledge) reflects on-call/escalation process -- how fast someone responds once alerted. Conflating them leads to fixing the wrong lever.', 'beginner'),
('devops', 'incident', 'fundamentals', 'Why does the fundamentals content say root-causing thoroughly still matters, even though it should not be a prerequisite to restoring service?', '["It doesn''t matter -- once service is restored, root cause is optional and often skipped entirely", "Root-causing happens in the post-mortem after service is restored, where it prevents recurrence -- the point is sequencing (mitigate first), not skipping root cause entirely", "Root cause analysis is only required for P1 incidents, never for P2 or P3", "Thorough root-causing should always happen before any mitigation is attempted, contradicting the restore-first principle"]', 1, 'The mindset shift is about order, not omission: mitigate to stop user impact first, then root-cause thoroughly in the post-mortem -- both matter, but doing them in the wrong order extends downtime unnecessarily.', 'intermediate'),
('devops', 'incident', 'fundamentals', 'What is the practical definition of ''blameless'' in a post-mortem culture, per the fundamentals content?', '["No post-mortem is ever written if a specific person''s mistake caused the incident", "The investigation asks what about the system allowed a human mistake to cause an outage, not who made the mistake -- since humans will always eventually make mistakes, the system that can be taken down by one is the actual thing worth fixing", "Blameless means the post-mortem is never shared outside the immediate team", "It means severity is always downgraded to avoid assigning responsibility"]', 1, 'Blameless specifically redirects the investigation from ''who made the mistake'' to ''what about the system allowed one mistake to cause an outage'' -- since people will always eventually err, the system''s resilience to that is the real fix.', 'advanced'),
('devops', 'incident', 'fundamentals', 'Why does a blame-assigning post-mortem culture reliably produce worse incident data over time, per the content?', '["It doesn''t -- blame-assigning cultures produce more accurate incident data because people are more careful", "People under-report their own mistakes and omit details that might look bad, and become reluctant to proactively raise ''this could go wrong'' concerns -- directly reducing the information quality a post-mortem needs to actually prevent recurrence", "Blame-assigning cultures are prohibited by most incident management tooling, making the comparison moot", "It only affects P4 incidents, which are low-stakes enough that data quality doesn''t matter"]', 1, 'The mechanism is behavioral: fear of blame causes people to hide details and stay quiet about risks -- exactly the information a post-mortem needs most, which is why blameless is framed as a practical requirement, not just a nice value.', 'advanced'),
('devops', 'chaos-engineering', 'overview', 'What is the core difference between what HA/DR designs for and what Chaos Engineering discovers?', '["They are the same practice, just applied at different scales", "HA/DR designs systems to survive known failure modes; Chaos Engineering discovers failure modes you have not thought of yet", "HA/DR only applies to Kubernetes; Chaos Engineering only applies to bare-metal servers", "Chaos Engineering replaces the need for HA/DR entirely"]', 1, 'The overview states this distinction directly: HA/DR handles failure modes already designed for, while chaos engineering''s specific purpose is surfacing failure modes nobody anticipated.', 'beginner'),
('devops', 'chaos-engineering', 'overview', 'In the chaos-engineering scientific method, what step comes immediately after defining steady state?', '["Run the experiment in production immediately", "Form a hypothesis (e.g. ''killing one replica will not affect user latency'')", "Fix weaknesses found", "Repeat until confident"]', 1, 'The scientific method sequence is: define steady state, then form a falsifiable hypothesis, then design the experiment with minimum blast radius, then run it (starting in staging).', 'beginner'),
('devops', 'chaos-engineering', 'overview', 'What is ''blast radius'' in the context of a chaos experiment?', '["The total cost of running the chaos engineering tool itself", "The scope of what''s affected if the experiment goes wrong -- one pod is a small blast radius, an entire Availability Zone is a large one", "The number of engineers required to run an experiment", "The time duration an experiment is scheduled to run for"]', 1, 'Blast radius specifically describes the scope of impact if an experiment goes wrong -- the overview and fundamentals both emphasize keeping it deliberately small (one pod, not an entire AZ) especially when starting out.', 'beginner'),
('devops', 'chaos-engineering', 'overview', 'Which of the listed safety rules specifically addresses when experiments should be run, and why?', '["Always have a kill switch to abort the experiment", "Run during business hours so the team can respond", "Keep blast radius small", "Start in staging, never production first"]', 1, 'The safety rules explicitly include running experiments during business hours specifically so the team is available to respond if something goes wrong -- distinct from the blast-radius and staging-first rules.', 'intermediate'),
('devops', 'chaos-engineering', 'overview', 'Which chaos tool is listed as best suited for AWS-native services (EC2, ECS, EKS, RDS)?', '["LitmusChaos", "Toxiproxy", "AWS Fault Injection Simulator", "Chaos Mesh"]', 2, 'AWS Fault Injection Simulator (FIS) is listed specifically for EC2/ECS/EKS/RDS on AWS, distinct from LitmusChaos/Chaos Mesh (Kubernetes-native) and Toxiproxy (application-level network faults).', 'beginner'),
('devops', 'chaos-engineering', 'fundamentals', 'Why is pod-delete described as the right starting experiment, not a toy example to skip past?', '["Because it is the only experiment any chaos tool supports", "It exercises the entire chaos-engineering loop (steady state, hypothesis, controlled injection, observation) against a failure mode Kubernetes is explicitly designed to handle -- so a failed experiment here reveals something genuinely wrong, like a missing PodDisruptionBudget", "Because it requires no monitoring or observation of any kind", "Because it is the most destructive experiment available and tests worst-case scenarios first"]', 1, 'Pod-delete exercises the full experimental loop against a failure mode Kubernetes should already handle -- if it fails, that reveals a genuine gap (missing PDB, insufficient replicas, a bad readiness probe), making it a meaningful starting point rather than a trivial one.', 'intermediate'),
('devops', 'chaos-engineering', 'fundamentals', 'What does FORCE: "false" specifically do in a LitmusChaos pod-delete ChaosEngine spec?', '["It disables the experiment entirely, so no pod is actually deleted", "It lets the pod terminate gracefully (respecting terminationGracePeriodSeconds and pre-stop hooks) rather than a hard kill -- the more realistic failure mode for most real-world pod loss like node drains", "It forces the experiment to run against production instead of staging", "It increases the blast radius to the entire deployment instead of one pod"]', 1, 'FORCE: "false" specifically triggers graceful termination (honoring grace periods and pre-stop hooks) rather than a hard kill, which better simulates common real-world pod loss like node drains or rolling updates.', 'intermediate'),
('devops', 'chaos-engineering', 'fundamentals', 'Why is ''the service should keep working'' considered a bad steady-state definition?', '["Because it is too specific and leaves no room for interpretation", "It is unfalsifiable -- there is no way to tell whether an observed change during the experiment is real impact or just ordinary variance, unlike a specific measurable claim (e.g. p99 latency under 200ms)", "Because steady state should only ever be defined after the experiment runs, not before", "Because Kubernetes does not expose any metrics that could measure ''working''"]', 1, 'A good steady-state definition has to be specific and measurable (e.g. p99 latency under 200ms, error rate under 0.1%) so it''s falsifiable -- ''keep working'' provides no way to distinguish real experiment impact from ordinary variance.', 'beginner'),
('devops', 'chaos-engineering', 'fundamentals', 'Which three practices are specifically listed as the core blast-radius safety approach when starting out with chaos engineering?', '["Run only on weekends, use the most expensive tool available, and notify no one in advance", "Start with one pod (not a whole deployment), start in staging before production, and always have a working, pre-tested abort mechanism", "Run the largest possible experiment first to save time, skip staging entirely, and disable all monitoring during the test", "Only test databases, never application services, and always run experiments at 3am"]', 1, 'The fundamentals content lists these three specifically: start with one pod not a whole deployment, start in staging and only move to production once confidence is earned, and always have a tested (not assumed) abort mechanism ready.', 'intermediate'),
('devops', 'chaos-engineering', 'fundamentals', 'Why does a chaos experiment that passed six months ago provide little confidence about today''s system?', '["Because chaos engineering results expire automatically after 90 days by definition", "Deployments, dependency changes, and scaling since then can all have silently reintroduced the exact failure mode that experiment once ruled out -- confidence requires routine, repeated testing, not a one-off pass", "Because Kubernetes versions are only supported for six months", "Because the original experiment''s results are deleted from the chaos tool after six months"]', 1, 'The content frames chaos engineering''s real value as a routine practice, not a one-off exercise -- system changes since a past passing experiment can silently reintroduce the same failure mode, so a stale pass gives false confidence.', 'advanced'),
('devops', 'chaos-engineering', 'intermediate', 'What failure category does network chaos (e.g. injecting 100ms latency between services) specifically expose that pod/instance-kill experiments miss entirely?', '["Disk space exhaustion on worker nodes", "A component that''s still running but responding slowly, intermittently, or partially -- revealing whether upstream services have real timeouts configured, or whether a slow dependency cascades into thread/connection-pool exhaustion", "Kubernetes RBAC misconfigurations", "Container image vulnerabilities"]', 1, 'Pod-kill tests a component disappearing outright; network chaos specifically tests a component that''s alive but slow -- a genuinely different failure mode that reveals missing timeout configuration and cascading resource exhaustion that hard-kill tests never exercise.', 'intermediate'),
('devops', 'chaos-engineering', 'intermediate', 'In a game day, what is described as the actual metric that matters, beyond whether the system technically survived?', '["The total dollar cost of running the chaos tooling during the exercise", "Time-to-detect and time-to-mitigate -- how long it took the team to notice and respond, since that''s exactly the gap that matters in a real outage", "The number of engineers who attended the game day session", "Whether the chaos experiment ran on the first attempt without any configuration errors"]', 1, 'A game day tests the team''s process, not just the system -- time-to-detect and time-to-mitigate are called out specifically as the metrics that matter, since a system surviving technically doesn''t tell you whether the team would have caught and responded to it in time during a real incident.', 'advanced'),
('devops', 'chaos-engineering', 'intermediate', 'What does the stopConditions field do in an AWS Fault Injection Simulator experiment definition?', '["It sets a maximum dollar budget for the experiment before AWS bills the account", "It automatically halts the experiment if a named CloudWatch alarm fires during the run -- a platform-level safety mechanism, not just an operator watching a dashboard", "It prevents the experiment from ever being run against production, regardless of configuration", "It requires manual approval from an AWS support engineer before each run"]', 1, 'stopConditions is FIS''s built-in safety mechanism -- the platform itself automatically halts a runaway experiment if a named CloudWatch alarm fires, rather than relying entirely on an operator noticing and manually aborting.', 'intermediate'),
('devops', 'chaos-engineering', 'intermediate', 'According to the content, what is the honest answer to the objection ''we already have monitoring and tests, why deliberately break things too''?', '["Monitoring and tests are strictly redundant with chaos engineering, so the objection is entirely correct and chaos engineering adds no value", "Tests and monitoring both verify what you already expect to happen; neither surfaces failure modes you have not imagined yet, which is specifically the gap chaos engineering fills", "Chaos engineering is only useful for teams that don''t already have monitoring in place", "Monitoring and tests are more expensive to maintain than a chaos engineering program, so chaos engineering should replace both"]', 1, 'The content''s honest framing: tests confirm designed behavior and monitoring alerts on already-defined thresholds -- neither reveals an unimagined failure mode, which is exactly the specific gap chaos engineering exists to fill.', 'advanced'),
('devops', 'chaos-engineering', 'intermediate', 'When prioritizing what to chaos-test next, what should take priority over exotic or unlikely failure combinations?', '["Whichever experiment is technically easiest to configure in the chosen tool", "Failure modes most likely to actually occur in production and least likely to have already been tested -- an untested critical dependency, a recent architecture change, or a component flagged by a past postmortem", "Whichever experiment produces the most visually impressive dashboard during a demo", "Experiments that specifically target the newest team member''s on-call shift"]', 1, 'The content is explicit: prioritize by actual production risk and testing gaps -- a critical dependency never simulated, a recent architecture change, or a postmortem-flagged untested assumption -- over chasing interesting-but-unlikely exotic scenarios.', 'intermediate'),
('devops', 'chaos-engineering', 'advanced', 'Why should only well-understood, previously-validated experiments be placed into an automated CI/CD chaos gate?', '["Because CI/CD pipelines cannot technically run any chaos tooling at all", "Automating an exploratory, higher-risk experiment into a blocking gate turns ''discover unknown weaknesses safely'' into ''randomly break the pipeline'' -- exactly the outcome that gets a chaos program disabled by a frustrated team within a month", "Because only well-understood experiments are supported by LitmusChaos''s CRD schema", "Because CI/CD gates can only run experiments that complete in under 10 seconds"]', 1, 'The advanced content is explicit about scope: automated gates should only contain experiments with known, validated blast radius -- exploratory or high-risk experiments (full AZ failure, novel combinations) stay as human-supervised game days, not automated gates.', 'advanced'),
('devops', 'chaos-engineering', 'advanced', 'Beyond the technical setup, what organizational requirement is specifically called out for simulating a full Availability Zone or region failure?', '["No special requirement -- it can be run the same way as a single pod-delete experiment", "Explicit executive sign-off, a defined and tested rollback path decided before the experiment starts (not designed reactively), and advance, maintenance-window-style scheduling communicated well ahead of time", "A dedicated new chaos engineering team hired specifically for this one experiment", "Written consent from every individual customer whose traffic might be affected"]', 1, 'Because this class of experiment is categorically higher-risk than a single pod-kill, the content specifically requires executive sign-off, a pre-defined (not reactive) rollback path, and advance scheduling communicated like a maintenance window -- not a surprise.', 'advanced'),
('devops', 'chaos-engineering', 'advanced', 'In ''security chaos engineering'', what does simulating a compromised or revoked service account credential mid-flow actually test?', '["Whether the credential rotation process completes within a specific number of milliseconds", "Whether dependent systems actually fail closed (deny access) rather than silently falling back to an insecure default, when the credential they rely on stops working", "Whether the security team can identify who originally issued the credential", "Whether the credential can be un-revoked automatically after a timeout"]', 1, 'The point is verifying actual behavior under the triggering condition -- confirming dependent systems fail closed (deny access) rather than silently degrading to an insecure fallback, since a security control never tested against a real trigger is a hypothesis, not a verified fact.', 'advanced'),
('devops', 'chaos-engineering', 'advanced', 'Per the chaos maturity model, what is described as the typical gap preventing a team from moving from ''Structured'' to ''Automated''?', '["A lack of any chaos tooling installed in the cluster", "The jump requires enough trust in a specific experiment''s safety to let it block a pipeline, which itself typically requires a track record of that exact experiment having been run manually and successfully many times first", "Automated chaos gates are technically impossible to build with any current tooling", "Structured teams are prohibited by their tooling license from automating experiments"]', 1, 'Moving to Automated requires trusting a specific experiment enough to let it gate a pipeline -- and that trust is earned only through a track record of the same experiment being run manually, successfully, many times first. The content frames plateauing at Structured as a normal, expected stage rather than a failure.', 'advanced'),
('devops', 'chaos-engineering', 'advanced', 'Why do most teams that adopt chaos engineering plateau at the ''Structured'' maturity level rather than progressing further?', '["Because ''Structured'' is technically the highest level any team can legally reach", "Reaching ''Automated'' requires a track record of trust in specific experiments earned through repeated manual runs, and reaching ''Continuous'' requires sustained organizational buy-in for higher-risk experiments -- both are realistically slow, expected stages, not failures to reach an idealized end state", "Because chaos engineering tools stop working correctly after the Structured phase", "Because regulatory requirements prohibit teams from automating chaos experiments"]', 1, 'The maturity model frames plateauing at Structured as normal and expected -- the jump onward requires either a proven trust track record (for Automated) or sustained executive buy-in for higher-risk experiments (for Continuous), both of which take real time to build, not a technical blocker.', 'advanced')
